<?php require __DIR__.'/../../app/core/bootstrap.php';$u=require_admin();require __DIR__.'/../../app/helpers/layout.php';render_start('Pengguna','Manajemen anggota mahasiswa',$u);dashboard_nav('admin');render_mid('Pengguna','Data seluruh pengguna',$u);$rows=$pdo->query("SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE r.name='pengguna' ORDER BY u.id DESC")->fetchAll();?><div class="card"><div class="toolbar"><div><b>Daftar Pengguna</b><p class="muted"><?=count($rows)?> pengguna terdaftar.</p></div><a class="btn btn-primary" href="/admin/users/create.php">+ Tambah Pengguna</a></div><div class="table-wrap"><table class="table"><thead><tr><th>NIM</th><th>Nama</th><th>Email</th><th>Kelas</th><th>Prodi</th><th>Semester</th><th>Status</th><th>Terakhir Login</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nim'])?></td><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['class_name'])?></td><td><?=e($r['study_program'])?></td><td><?=e($r['semester'])?></td><td><span class="badge <?=$r['status']==='aktif'?'green':'red'?>"><?=e($r['status'])?></span></td><td><?=e($r['last_login_at']??'—')?></td></tr><?php endforeach;?></tbody></table></div></div><?php render_end(); ?>
